// CPU breakdown in ms attributed by the profiler.
const costs = [
  { name: 'megamorphic-load', ms: 60 },
  { name: 'gc-churn', ms: 25 },
  { name: 'deopt-loop', ms: 10 },
  { name: 'misc', ms: 5 },
];

function dominant(list) {
  return list.reduce((a, b) => (b.ms > a.ms ? b : a));
}
function total(list) {
  return list.reduce((s, c) => s + c.ms, 0);
}

const before = dominant(costs);
// Apply the fix for the dominant cost: that cost goes to 0.
const after = costs.map(c => c.name === before.name ? { ...c, ms: 0 } : c);
const nextDominant = dominant(after);
console.log('fixed=' + before.name + ' nextDominant=' + nextDominant.name + ' newTotal=' + total(after));

