function buildRollup(event) {
  const out = {
    tenantId: event.tenantId,
    count: 0,
    sum: 0,
  };
  out.count = event.count;
  out.sum = event.sum;
  if (event.label) {
    out.label = event.label;   // only sometimes present
  }
  return out;
}
